auto now = id(sntp_time).now();
if (!now.is_valid()) return;
int now_min = now.hour * 60 + now.minute;
int from_min = id(available_from).hour * 60 + id(available_from).minute;
int until_min = id(available_until).hour * 60 + id(available_until).minute;

bool available;
if (from_min <= until_min) {
  available = (now_min >= from_min && now_min < until_min);
} else {
  // Window wraps past midnight.
  available = (now_min >= from_min || now_min < until_min);
}

